SELECT

FROM sys_notify_todo

    AND field_id = #{model.fieldId}
    AND field_name LIKE CONCAT('%', #{model.fieldName}, '%')
    AND field_model_name LIKE CONCAT('%', #{model.fieldModelName}, '%')
    AND field_model_id = #{model.fieldModelId}
    AND field_notify_type = #{model.fieldNotifyType}

ORDER BY field_create_time DESC


    LIMIT #{pages.pageSize} OFFSET #{offset}

SELECT m.field_id, m.field_name, m.field_model_name, m.field_notify_type, m.field_create_time, IFNULL(t.receive_count, 0) AS field_receive_count, IFNULL(t.done_count, 0) AS field_done_count FROM sys_notify_todo m LEFT JOIN ( SELECT field_todo_id, COUNT(*) AS receive_count, SUM(CASE WHEN field_is_done = 1 THEN 1 ELSE 0 END) AS done_count FROM sys_notify_todo_target GROUP BY field_todo_id ) t ON t.field_todo_id = m.field_id
AND m.field_notify_type = #{model.fieldNotifyType} AND m.field_model_name = #{model.fieldModelName} AND m.field_name LIKE CONCAT('%', #{model.fieldName}, '%') AND m.field_create_time >= #{model.fieldCreateTimeStart} AND m.field_create_time <= #{model.fieldCreateTimeEnd}
ORDER BY
m.field_create_time m.field_create_time
ASC DESC
LIMIT #{pages.pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM sys_notify_todo m

    AND m.field_notify_type = #{model.fieldNotifyType}
    AND m.field_model_name = #{model.fieldModelName}
    AND m.field_name LIKE CONCAT('%', #{model.fieldName}, '%')
    AND m.field_create_time >= #{model.fieldCreateTimeStart}
    AND m.field_create_time <= #{model.fieldCreateTimeEnd}

